#!/usr/bin/env python3
"""Regenerate events/keys/keys.js, the organizer key list shown in the PGP KEYS section.

The keys are only for verifying announcements; publishing events does not use them
(see add_event.py and events/organizers.txt).
"""
import glob
import json
import os
import subprocess
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
KEYS_DIR = os.path.join(ROOT, 'events', 'keys')
KEYS_JS = os.path.join(KEYS_DIR, 'keys.js')


def fingerprints(home, path):
    shown = subprocess.run(['gpg', '--homedir', home, '--batch', '--no-tty', '--with-colons', '--show-keys', path],
                           capture_output=True)
    lines = shown.stdout.decode('utf-8', 'replace').splitlines()
    return [lines[i + 1].split(':')[9] for i, line in enumerate(lines)
            if line.startswith('pub:') and i + 1 < len(lines) and lines[i + 1].startswith('fpr:')]


def main():
    with tempfile.TemporaryDirectory() as home:
        os.chmod(home, 0o700)
        keys = []
        for path in sorted(glob.glob(os.path.join(KEYS_DIR, '*.asc'))):
            fprs = fingerprints(home, path)
            if fprs:
                keys.append({'handle': os.path.splitext(os.path.basename(path))[0],
                             'file': os.path.basename(path), 'fingerprints': fprs})
    js = json.dumps(keys, ensure_ascii=False, indent=2).replace('</', '<\\/')
    with open(KEYS_JS, 'w', encoding='utf-8') as f:
        f.write('/* Generated by .github/scripts/build_keys.py from events/keys/*.asc. Do not edit by hand. */\n'
                'window.ORGANIZER_KEYS = ' + js + ';\n')
    print(f'{len(keys)} key(s) written to {KEYS_JS}')


if __name__ == '__main__':
    main()
